"""Kickoff 54 analysis, fixed before the data (section 3 of the kickoff; k54-rule.md).

The verdict: Kickoff 53's analysis on twelve cells, by analyse_53.py's functions unchanged (a byte-identical copy),
with its bootstrap seed set to 54 as k54-rule.md fixes it. Its helpers come from the repository's tests/_reuse_runs.py
at e45f15d, whose pct and _wait_test_keys are identical to a55354d's. Only the verdict's 96 positions are passed to it
(parts W and R); the circuits beside the verdict (part B) are not.

H54: DISAGREE if any informative cell's d1 interval lies entirely outside [-0.15, +0.15]; AGREE if every informative
cell's lies entirely inside; NOT SETTLED otherwise; ", uninformative" if no cell is informative (loss_R1 interval
entirely above 0.2).

Beside the verdict (k54-rule.md's list), from their own bootstrap, seed 54, 10,000 draws, in a fixed order: per M in
the rule's chain order, P(1) of Z, X1, XY4, R1 at 0, 90, 180, 270; then, on 144 and 143, the single-neighbour Ramseys
(idle, L1, L3, both) at 0, 90, 180, 270 (copies with replacement, each redrawn binomially), refitting on every resample:
  1. the original rule (d0 with R0, the package's idle Ramsey) and its verdict: from analyse_53's own result;
  2. the lean: each d1, the mean d1, the cells with d1 above zero;
  3. P(0|1) on each M: 1 - P(1) after X, measure;
  4. the pulses' cost on each M: P(1) after H, the four XY4 pulses back to back, H (and minus Z's P(1));
  5. R1 at 0, 90, 180, 270 on every chain: loss fitted as c + b cos(phi) + s sin(phi) by OLS, theta = atan2(s, -b),
     amplitude sqrt(b^2 + s^2) (Kickoff 52's convention);
  6. on 144 (143-144-145) and 143 (144-143-142): the four single-neighbour Ramseys fitted as in 5; each shift = the
     variant's theta minus the both-idle theta, wrapped to (-180, +180]; the 143-144 pair seen from each side (from 144
     with only 143 in |1>, from 143 with only 144 in |1>, both L1) and their difference; on each qubit the sum of the
     two single shifts against the both shift; and the neighbours' measured bits per variant.

Usage: python analyse_54.py                 (Kickoff 54's files)
       python analyse_54.py --synthetic     (verdict built to AGREE and to DISAGREE; fits with a known theta)"""
from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from collections import defaultdict
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / "site"))
sys.path.insert(0, str(HERE / "src-e45f15d" / "tests"))
sys.path.insert(0, str(HERE))
import analyse_53 as A53  # noqa: E402  Kickoff 53's functions, unchanged

A53.SEED = 54                       # the verdict's bootstrap seed (k54-rule.md)
ORDER = ["30", "74", "121", "103", "144", "143"]   # the rule's chain order, by M
PHIS4 = (0, 90, 180, 270)
NEIGHBOUR_M = ("144", "143")
VARIANTS = ("idle", "L1", "L3", "both")
SEED_B, N_BOOT = 54, 10_000
_X4 = np.column_stack([np.ones(4), np.cos(np.radians(PHIS4)), np.sin(np.radians(PHIS4))])
_P4 = np.linalg.pinv(_X4)
pct = A53.pct


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def wrap(x):
    w = (np.asarray(x, float) + 180.0) % 360.0 - 180.0
    return np.where(w <= -180.0, w + 360.0, w)


def fit4(y):
    """OLS of loss(phi) = c + b cos(phi) + s sin(phi) over 0, 90, 180, 270; theta = atan2(s, -b), amplitude."""
    coef = np.asarray(y, float) @ _P4.T
    c, b, s = coef[..., 0], coef[..., 1], coef[..., 2]
    return np.degrees(np.arctan2(s, -b)), np.hypot(b, s), c, b, s


def tallies(labels, counts):
    """(M, circuit, phi) -> [(copy, ones on the bit, shots)] for M's bit; and the neighbours' bits where measured."""
    m_bits, n_bits = defaultdict(list), defaultdict(list)
    for lab, cts in zip(labels, counts):
        if lab["part"] == "W":
            continue
        key = (str(lab["M"]), lab["circuit"], lab["phi_deg"])
        bit = lambda i: sum(n for k, n in cts.items() if k.replace(" ", "")[::-1][i] == "1")
        tot = sum(cts.values())
        m_bits[key].append((lab["copy"], bit(lab["m_clbit"]), tot))
        if "l1_clbit" in lab:
            n_bits[key].append((lab["copy"], bit(lab["l1_clbit"]), bit(lab["l3_clbit"]), tot))
    for d in (m_bits, n_bits):
        for k in d:
            d[k].sort(key=lambda x: x[0])
    return m_bits, n_bits


def beside(labels, counts):
    m_bits, n_bits = tallies(labels, counts)
    rng = np.random.default_rng(SEED_B)

    def draw(key):
        o = np.array([x[1] for x in m_bits[key]])
        t = np.array([x[2] for x in m_bits[key]])
        acc1, accn = np.zeros(N_BOOT), np.zeros(N_BOOT)
        for _ in range(len(o)):
            pick = rng.integers(0, len(o), size=N_BOOT)
            acc1 += rng.binomial(t[pick], o[pick] / t[pick])
            accn += t[pick]
        return acc1 / accn

    P = {k: sum(x[1] for x in v) / sum(x[2] for x in v) for k, v in m_bits.items()}
    out = {"readout_P0_given_1": {}, "pulse_cost": {}, "R1_fit": {}, "neighbours": {}}
    Pb = {}
    for M in ORDER:
        keys = [(M, "Z", 0), (M, "X1", 0), (M, "XY4", 0)] + [(M, "R1", p) for p in PHIS4]
        for k in keys:
            Pb[k] = draw(k)
        z, zb = P[(M, "Z", 0)], Pb[(M, "Z", 0)]
        out["readout_P0_given_1"][M] = {"P0_given_1": 1 - P[(M, "X1", 0)], "ci90": pct(1 - Pb[(M, "X1", 0)])}
        out["pulse_cost"][M] = {"P1": P[(M, "XY4", 0)], "P1_ci90": pct(Pb[(M, "XY4", 0)]),
                                "P1_minus_Z": P[(M, "XY4", 0)] - z, "P1_minus_Z_ci90": pct(Pb[(M, "XY4", 0)] - zb)}
        y = np.array([P[(M, "R1", p)] - z for p in PHIS4])
        yb = np.stack([Pb[(M, "R1", p)] - zb for p in PHIS4], -1)
        th, amp, c, b, s = fit4(y)
        thb, ampb, *_ = fit4(yb)
        out["R1_fit"][M] = {"loss": dict(zip(map(str, PHIS4), y.tolist())), "theta_deg": float(th), "theta_ci90": pct(th + wrap(thb - th)),
                            "amplitude": float(amp), "amplitude_ci90": pct(ampb), "c": float(c),
                            "residuals": (y - _X4 @ np.array([c, b, s])).tolist(), "label": "a fit (OLS over the four phases), fixed before the data"}
    for M in NEIGHBOUR_M:
        z, zb = P[(M, "Z", 0)], Pb[(M, "Z", 0)]
        th, thb, fits = {}, {}, {}
        for v in VARIANTS:
            ks = [(M, f"N-{v}", p) for p in PHIS4]
            for k in ks:
                Pb[k] = draw(k)
            y = np.array([P[k] - z for k in ks])
            yb = np.stack([Pb[k] - zb for k in ks], -1)
            t_, amp, c, b, s = fit4(y)
            tb, ampb, *_ = fit4(yb)
            th[v], thb[v] = float(t_), tb
            nb = {str(p): {"L1_P1": sum(x[1] for x in n_bits[(M, f"N-{v}", p)]) / sum(x[3] for x in n_bits[(M, f"N-{v}", p)]),
                           "L3_P1": sum(x[2] for x in n_bits[(M, f"N-{v}", p)]) / sum(x[3] for x in n_bits[(M, f"N-{v}", p)])} for p in PHIS4}
            fits[v] = {"loss": dict(zip(map(str, PHIS4), y.tolist())), "theta_deg": float(t_), "theta_ci90": pct(t_ + wrap(tb - t_)),
                       "amplitude": float(amp), "amplitude_ci90": pct(ampb), "residuals": (y - _X4 @ np.array([c, b, s])).tolist(),
                       "neighbour_bits_P1": nb}
        shift = {v: float(wrap(th[v] - th["idle"])) for v in ("L1", "L3", "both")}
        shift_b = {v: shift[v] + wrap(wrap(thb[v] - thb["idle"]) - shift[v]) for v in ("L1", "L3", "both")}
        ssum = float(wrap(shift["L1"] + shift["L3"]))
        ssum_b = ssum + wrap(wrap(shift_b["L1"] + shift_b["L3"]) - ssum)
        out["neighbours"][M] = {"fits": fits, "shift_deg": shift, "shift_ci90": {v: pct(shift_b[v]) for v in shift},
                                "sum_of_singles_deg": ssum, "sum_of_singles_ci90": pct(ssum_b),
                                "sum_minus_both_deg": float(wrap(ssum - shift["both"])), "sum_minus_both_ci90": pct(float(wrap(ssum - shift["both"])) + wrap((ssum_b - shift_b["both"]) - float(wrap(ssum - shift["both"])))),
                                "_shift_L1_draws": shift_b["L1"]}
    a, bq = out["neighbours"]["144"], out["neighbours"]["143"]
    d = float(wrap(a["shift_deg"]["L1"] - bq["shift_deg"]["L1"]))
    db = d + wrap((a["_shift_L1_draws"] - bq["_shift_L1_draws"]) - d)
    out["pair_143_144"] = {"from_144_only_143_in_1": a["shift_deg"]["L1"], "from_144_ci90": a["shift_ci90"]["L1"],
                           "from_143_only_144_in_1": bq["shift_deg"]["L1"], "from_143_ci90": bq["shift_ci90"]["L1"],
                           "difference_deg": d, "difference_ci90": pct(db)}
    for M in NEIGHBOUR_M:
        out["neighbours"][M].pop("_shift_L1_draws")
    return out


def analyse(labels, counts):
    vl = [(l, c) for l, c in zip(labels, counts) if l["part"] in ("W", "R")]
    r = A53.analyse([l for l, _ in vl], [c for _, c in vl], ORDER)
    d1 = [c["d1"] for c in r["cells"]]
    lean = {"d1": {c["cell"]: c["d1"] for c in r["cells"]}, "mean_d1": float(np.mean(d1)), "n_d1_above_zero": int(sum(x > 0 for x in d1)), "n_cells": len(d1),
            "mean_d1_informative": float(np.mean([c["d1"] for c in r["cells"] if c["informative_R1"]])) if r["informative_cells"] else None}
    return {"H54": r["H53"], "informative_cells": r["informative_cells"], "cells": r["cells"], "chains": r["chains"],
            "original_rule_and_comparison": r["beside"], "lean": lean, "beside": beside(labels, counts)}


def synthetic():
    """Counts drawn from stated distributions through the same code. Six chains (the rule's M names; R0 on one bit, as
    the package's idle Ramsey). AGREE: the wait test's offset equals R1's on every chain. DISAGREE: 40 degrees apart on
    one chain. Fits: R1 offsets stated per chain; single-neighbour offsets stated so that the shifts are known."""
    W = A53.W
    ideal = W.wait_test_ideal()
    ik = sorted(ideal)
    rng = np.random.default_rng(7)

    def w_counts(f, n):
        p = {k: f / 32 for k in ik}
        p["000001"] = 1 - f
        ks = list(p)
        x = rng.multinomial(n, [p[k] for k in ks])
        return {k: int(v) for k, v in zip(ks, x) if v}

    def r_counts(p1, n, bits=6, extra=None):
        o = int(rng.binomial(n, min(max(p1, 0.0), 1.0)))
        if bits == 1:
            return {"0": n - o, "1": o}
        lo = "0" * (bits - 1) if not extra else extra
        return {"0" + lo: n - o, "1" + lo: o}

    s2 = lambda x: math.sin(math.radians(x) / 2) ** 2
    c2 = lambda x: math.cos(math.radians(x) / 2) ** 2
    thR1 = {"30": 15, "74": -40, "121": 100, "103": -150, "144": -15, "143": -110}
    thN = {"144": {"idle": 5, "L1": -25, "L3": -40, "both": -70}, "143": {"idle": -98, "L1": -110, "L3": -120, "both": -135}}
    ok = True
    for name, extra in (("AGREE", {}), ("DISAGREE", {"121": 40})):
        labels, counts = [], []
        for M in ORDER:
            t1 = thR1[M]
            for cp in (1, 2):
                for p in (0, 90):
                    labels.append({"M": int(M), "part": "W", "circuit": "W-no", "phi_deg": p, "copy": cp}); counts.append(w_counts(0.9 * c2(p + t1 + extra.get(M, 0)), 3500))
                    labels.append({"M": int(M), "part": "R", "circuit": "R1", "phi_deg": p, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01 + 0.9 * s2(p + t1), 3500))
                    labels.append({"M": int(M), "part": "R", "circuit": "R0", "phi_deg": p, "copy": cp, "m_clbit": 0}); counts.append(r_counts(0.01 + 0.9 * s2(p + t1 + 20), 3500, bits=1))
                for p in (180, 270):
                    labels.append({"M": int(M), "part": "B", "circuit": "R1", "phi_deg": p, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01 + 0.9 * s2(p + t1), 1500))
                labels.append({"M": int(M), "part": "W", "circuit": "W-ref", "phi_deg": 0, "copy": cp}); counts.append(w_counts(0.9, 3500))
                labels.append({"M": int(M), "part": "R", "circuit": "Z", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01, 3500))
                labels.append({"M": int(M), "part": "B", "circuit": "X1", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.97, 1500))
                labels.append({"M": int(M), "part": "B", "circuit": "XY4", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.02, 1500))
                if M in thN:
                    for v in VARIANTS:
                        nb = {"idle": "00000", "L1": "00001", "L3": "00010", "both": "00011"}[v]
                        for p in PHIS4:
                            labels.append({"M": int(M), "part": "B", "circuit": f"N-{v}", "phi_deg": p, "copy": cp, "m_clbit": 5, "l1_clbit": 0, "l3_clbit": 1})
                            counts.append(r_counts(0.01 + 0.9 * s2(p + thN[M][v]), 1500, extra=nb))
        r = analyse(labels, counts)
        good = r["H54"].startswith(name)
        ok = ok and good
        print(f"synthetic built to {name}: got {r['H54']} | informative {r['informative_cells']} | {'PASS' if good else 'FAIL'}")
        if name == "AGREE":
            b = r["beside"]
            fit_ok = all(abs(b["R1_fit"][M]["theta_deg"] - thR1[M]) < 3 for M in ORDER)
            exp = {M: {v: thN[M][v] - thN[M]["idle"] for v in ("L1", "L3", "both")} for M in thN}
            sh_ok = all(abs(b["neighbours"][M]["shift_deg"][v] - exp[M][v]) < 3 for M in thN for v in exp[M])
            print("  R1 fits:", {M: round(b["R1_fit"][M]["theta_deg"], 1) for M in ORDER}, "stated", thR1, "PASS" if fit_ok else "FAIL")
            print("  shifts:", {M: {v: round(x, 1) for v, x in b["neighbours"][M]["shift_deg"].items()} for M in thN}, "stated", exp, "PASS" if sh_ok else "FAIL")
            print("  pair:", {k: (round(v, 1) if isinstance(v, float) else v) for k, v in b["pair_143_144"].items()}, "| P(0|1):", {M: round(v["P0_given_1"], 3) for M, v in b["readout_P0_given_1"].items()})
            ok = ok and fit_ok and sh_ok
    print("synthetic overall:", "PASS" if ok else "FAIL")
